import { connection } from 'next/server'

type UserPreferences = Record<string, unknown>

// User-specific data that must be fetched fresh on every request
async function getUserPreferences(): Promise<UserPreferences | null> {
  try {
    const res = await fetch('https://api.example.com/user/preferences', {
      cache: 'no-store',
    })
    if (!res.ok) return null
    return res.json()
  } catch {
    return null
  }
}

export default async function UserDashboard() {
  // Opt out of prerendering so this only runs at request time. Called outside
  // the try/catch so Next.js's dynamic-rendering signal isn't swallowed.
  await connection()
  const preferences = await getUserPreferences()

  return (
    <div>
      <h2>User Dashboard</h2>
      {preferences ? (
        <ul>
          {Object.entries(preferences).map(([key, value]) => (
            <li key={key}>
              {key}: {typeof value === 'object' ? JSON.stringify(value) : String(value)}
            </li>
          ))}
        </ul>
      ) : (
        <p>Unable to load user preferences.</p>
      )}
    </div>
  )
}

